import { Env, EventContext } from './types';
import { isStagingHost } from './utils/seo';

/**
 * Root middleware for every Pages Function route on the public site.
 *
 * Cloudflare Pages does not apply the public/_headers file to responses generated by
 * Functions (article pages under /news/*, the API, RSS, sitemaps, newsletter pages),
 * so the same security headers are set here. Keep this list in sync with public/_headers.
 */
const SECURITY_HEADERS: Record<string, string> = {
  'X-Frame-Options': 'DENY',
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=(), payment=()',
  'Strict-Transport-Security': 'max-age=31536000; includeSubDomains',
  'Content-Security-Policy': [
    "default-src 'self'",
    "script-src 'self' 'unsafe-inline' https://challenges.cloudflare.com https://static.cloudflareinsights.com",
    "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
    "font-src 'self' https://fonts.gstatic.com data:",
    "img-src 'self' data: https: blob:",
    "connect-src 'self' https://challenges.cloudflare.com https://api.open-meteo.com https://cloudflareinsights.com",
    'frame-src https://challenges.cloudflare.com',
    "object-src 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    "frame-ancestors 'none'",
  ].join('; '),
};

export async function onRequest(context: EventContext<Env, any, any>): Promise<Response> {
  let response: Response;
  try {
    response = await context.next();
  } catch (err) {
    console.error('Unhandled function error:', err);
    response = new Response(JSON.stringify({ error: 'Internal server error' }), {
      status: 500,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  // Copy so headers are mutable (responses from fetch/assets can be immutable)
  const secured = new Response(response.body, response);
  for (const [name, value] of Object.entries(SECURITY_HEADERS)) {
    secured.headers.set(name, value);
  }

  // Keep out of Google: raw JSON from the API (crawlers may still fetch it so the app can draw its pages),
  // and every copy of the site on Cloudflare's own *.pages.dev / *.workers.dev addresses.
  const url = new URL(context.request.url);
  if (url.pathname.startsWith('/api/') || isStagingHost(url.hostname)) {
    secured.headers.set('X-Robots-Tag', 'noindex');
  }
  return secured;
}
